(function(){
 var section=document.getElementById('logo-downloads');
 if(!section)return;
 var image=document.getElementById('tbmLogoPng'),links=section.querySelectorAll('[data-logo-filename]');
 var feedback=document.getElementById('tbmLogoFeedback'),ready=false;
 feedback.textContent='Menyiapkan PNG transparan…';
 links.forEach(function(link){link.addEventListener('click',function(event){
  event.preventDefault();
  if(!ready){feedback.textContent='PNG sedang disiapkan. Tunggu sebentar, lalu pilih Unduh PNG.';return;}
  var download=document.createElement('a');
  download.href=link.href;download.download='Logo-TBM-Cs.png';download.style.display='none';
  document.body.appendChild(download);download.click();download.remove();
  feedback.textContent='Unduhan Logo-TBM-Cs.png diminta. Periksa daftar unduhan browser Anda.';
 });});
 function fail(){feedback.textContent='PNG belum dapat disiapkan. Muat ulang halaman atau coba browser lain.';}
 image.addEventListener('load',function(){
  try{
   var canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;
   var context=canvas.getContext('2d');if(!context)throw new Error('Canvas unavailable');
   context.clearRect(0,0,canvas.width,canvas.height);
   context.drawImage(image,0,0);
   var pixels=context.getImageData(0,0,canvas.width,canvas.height).data;
   var transparent=false;
   for(var p=3;p<pixels.length;p+=4){if(pixels[p]===0){transparent=true;break;}}
   if(!transparent)throw new Error('Transparency missing');
   canvas.toBlob(function(blob){
    if(!blob||blob.type!=='image/png'){fail();return;}
    blob.slice(0,8).arrayBuffer().then(function(buffer){
     var signature=new Uint8Array(buffer),png=[137,80,78,71,13,10,26,10];
     if(!png.every(function(value,index){return signature[index]===value;})){fail();return;}
     var url=URL.createObjectURL(blob);
     // Both the preview and the button now reference the same verified PNG.
     image.src=url;
     links.forEach(function(link){link.href=url;link.download='Logo-TBM-Cs.png';link.removeAttribute('aria-disabled');});
     ready=true;feedback.textContent='PNG transparan siap diunduh.';
    }).catch(fail);
   },'image/png');
  }catch(error){fail();}
 },{once:true});
 image.addEventListener('error',fail,{once:true});
 image.src='data:image/webp;base64,'+["","","","","","","","","","","","","","","","","","","","","","","",""].join('');
 if(location.hash==='#logo-downloads')requestAnimationFrame(function(){section.scrollIntoView({block:'start',behavior:'auto'});});
}());
